export const KIND = {"id":64,"example":{"id":"E64","kind":64,"source":"aether","statement":["Write a function `rod::best_price(int total, const std::vector<rod::Piece>& pieces)` that returns the largest sum of prices of pieces you can cut from a rod of length `total`, any number of each piece, whose lengths add up to at most `total`.","Write also the struct `rod::Piece`, with two `int` members, `length` then `price`.","With no pieces it returns 0.","Limits: 0 ≤ pieces ≤ 100; 1 ≤ total ≤ 1000; 1 ≤ each length ≤ 1000; 1 ≤ each price ≤ 1000."],"examples":[],"tests":[],"solution":{"lines":["#pragma once","","#include <algorithm>","#include <vector>","","namespace rod {","","struct Piece {","    int length {0};","    int price {0};","};","","int best_price(int total, const std::vector<Piece>& pieces)","{","    std::vector<int> best(total + 1, 0);","    for (const Piece& piece : pieces) {","        for (int size {piece.length}; size <= total; ++size) {","            const int with {best[size - piece.length]","                            + piece.price};","            best[size] = std::max(best[size], with);","        }","    }","    return best.back();","}","","}  // namespace rod"],"frame":[0,2,3,5,10,25],"labels":[{"at":7,"level":1,"text":"Write a struct that holds several values together."},{"at":7,"level":0,"text":"Make a type that holds several values with `struct`, whose members anyone may reach."},{"at":12,"level":1,"text":"Write a function that keeps the best value for each weight, one item at a time."},{"at":14,"level":2,"text":"Start the best price for each length from 0 to the total at 0."},{"at":14,"level":0,"text":"Make a list of n + 1 zeros with `std::vector<int> best(n + 1, 0)`, the size first, then the value."},{"at":15,"level":2,"text":"For each piece, keep the larger of the best price without it and with it, shortest length first."},{"at":15,"level":0,"text":"Take each item of a list in turn, without copying it, with `const Piece& piece`."},{"at":16,"level":0,"text":"Reach a member of a struct with `.`, as in `piece.length`."},{"at":22,"level":2,"text":"Give back the best price for the total length."},{"at":22,"level":0,"text":"Get the last item of a list with `back()`."}],"blanks":[]}},"trace":{"id":"T64","lines":["#include <algorithm>","#include <iostream>","#include <print>","#include <vector>","","int main()","{","    int most {0};","    std::cin >> most;","    std::vector<int> top(most + 1, 0);","    int size {0};","    while (std::cin >> size) {","        for (int w {most}; w >= size; --w) {","            top[w] = std::max(top[w], top[w - size] + size);","        }","    }","    std::println(\"{}\", top.back());","}"],"columns":["most","top","size","w"],"inputs":["3\n2\n","6\n4 3 2\n"],"rows":[{"line":8,"values":["0","","",""]},{"line":9,"values":["3","","",""]},{"line":10,"values":["3","[0, 0, 0, 0]","",""]},{"line":11,"values":["3","[0, 0, 0, 0]","0",""]},{"line":12,"values":["3","[0, 0, 0, 0]","2",""]},{"line":13,"values":["3","[0, 0, 0, 0]","2","3"]},{"line":14,"values":["3","[0, 0, 0, 2]","2","3"]},{"line":13,"values":["3","[0, 0, 0, 2]","2","2"]},{"line":14,"values":["3","[0, 0, 2, 2]","2","2"]},{"line":13,"values":["3","[0, 0, 2, 2]","2",""]},{"line":12,"values":["3","[0, 0, 2, 2]","2",""]},{"line":17,"values":["3","[0, 0, 2, 2]","2",""]}],"output":"6\n"},"traces":[],"problems":{"64.01":{"id":"64.01","kind":64,"source":"exercism","statement":["Write a struct `knapsack::Item` with two `int` members, `weight` then `value`.","Write a function `knapsack::maximum_value(int maximum_weight, const std::vector<knapsack::Item>& items)` that returns the largest sum of values of items you can choose, each item at most once, whose weights add up to at most `maximum_weight`.","With no items it returns 0.","Limits: 0 ≤ items ≤ 100; 1 ≤ maximum_weight ≤ 1000; 1 ≤ each weight ≤ 1000; 1 ≤ each value ≤ 1000."],"examples":[{"input":"no items","output":""}],"tests":[{"input":"one item, too heavy","output":""},{"input":"five items (cannot be greedy by weight)","output":""},{"input":"five items (cannot be greedy by value)","output":""},{"input":"example knapsack","output":""},{"input":"8 items","output":""},{"input":"15 items","output":""}],"solution":{"lines":["#pragma once","","#include <algorithm>","#include <vector>","","namespace knapsack {","","struct Item {","    int weight {0};","    int value {0};","};","","int maximum_value(int maximum_weight,","                  const std::vector<Item>& items)","{","    std::vector<int> best(maximum_weight + 1, 0);","    for (const Item& item : items) {","        for (int w {maximum_weight}; w >= item.weight; --w) {","            const int with {best[w - item.weight] + item.value};","            best[w] = std::max(best[w], with);","        }","    }","    return best.back();","}","","}  // namespace knapsack"],"frame":[0,2,3,5,10,25],"labels":[{"at":7,"level":1,"text":"Write a struct that holds several values together."},{"at":12,"level":1,"text":"Write a function that keeps the best value for each weight, one item at a time."},{"at":15,"level":2,"text":"Start the best value for each weight from 0 to the most at 0."},{"at":16,"level":2,"text":"For each item, keep the larger of the best value without it and with it, heaviest weight first."},{"at":22,"level":2,"text":"Give back the best value for the most weight."}],"blanks":[{"line":8,"from":16,"to":17},{"line":13,"from":18,"to":48},{"line":15,"from":46,"to":47},{"line":19,"from":22,"to":45},{"line":22,"from":11,"to":22}]},"fn":{"slug":"knapsack","commit":"8d139cb0","header":"knapsack.h","name":"knapsack_test.cpp","test":"#include \"knapsack.h\"\n\n#include <vector>\n#ifdef EXERCISM_TEST_SUITE\n#include <catch2/catch.hpp>\n#else\n#include \"test/catch.hpp\"\n#endif\n\nTEST_CASE(\"no items\", \"[maximumValue][3993a824-c20e-493d-b3c9-ee8a7753ee59]\") {\n    int max_weight = 100;\n    const std::vector<knapsack::Item> items{};\n    REQUIRE(knapsack::maximum_value(max_weight, items) == 0);\n}\n\n#if defined(EXERCISM_RUN_ALL_TESTS)\n\nTEST_CASE(\"one item, too heavy\",\n          \"[maximumValue][1d39e98c-6249-4a8b-912f-87cb12e506b0]\") {\n    int max_weight = 10;\n    const std::vector<knapsack::Item> items{{100, 1}};\n    REQUIRE(knapsack::maximum_value(max_weight, items) == 0);\n}\n\nTEST_CASE(\"five items (cannot be greedy by weight)\",\n          \"[maximumValue][833ea310-6323-44f2-9d27-a278740ffbd8]\") {\n    int max_weight = 10;\n    const std::vector<knapsack::Item> items{\n        {2, 5}, {2, 5}, {2, 5}, {2, 5}, {10, 21}};\n    REQUIRE(knapsack::maximum_value(max_weight, items) == 21);\n}\n\nTEST_CASE(\"five items (cannot be greedy by value)\",\n          \"[maximumValue][277cdc52-f835-4c7d-872b-bff17bab2456]\") {\n    int max_weight = 10;\n    const std::vector<knapsack::Item> items{\n        {2, 20}, {2, 20}, {2, 20}, {2, 20}, {10, 50}};\n    REQUIRE(knapsack::maximum_value(max_weight, items) == 80);\n}\n\nTEST_CASE(\"example knapsack\",\n          \"[maximumValue][81d8e679-442b-4f7a-8a59-7278083916c9]\") {\n    int max_weight = 10;\n    const std::vector<knapsack::Item> items{{5, 10}, {4, 40}, {6, 30}, {4, 50}};\n    REQUIRE(knapsack::maximum_value(max_weight, items) == 90);\n}\n\nTEST_CASE(\"8 items\", \"[maximumValue][f23a2449-d67c-4c26-bf3e-cde020f27ecc]\") {\n    int max_weight = 104;\n    const std::vector<knapsack::Item> items{{25, 350}, {35, 400}, {45, 450},\n                                            {5, 20},   {25, 70},  {3, 8},\n                                            {2, 5},    {2, 5}};\n    REQUIRE(knapsack::maximum_value(max_weight, items) == 900);\n}\n\nTEST_CASE(\"15 items\", \"[maximumValue][7c682ae9-c385-4241-a197-d2fa02c81a11]\") {\n    int max_weight = 750;\n    const std::vector<knapsack::Item> items{\n        {70, 135},  {73, 139},  {77, 149},  {80, 150},  {82, 156},\n        {87, 163},  {90, 173},  {94, 184},  {98, 192},  {106, 201},\n        {110, 210}, {113, 214}, {115, 221}, {118, 229}, {120, 240}};\n    REQUIRE(knapsack::maximum_value(max_weight, items) == 1458);\n}\n\n#endif  // EXERCISM_RUN_ALL_TESTS\n","setup":["int max_weight = 100;","const std::vector<knapsack::Item> items{};"],"calls":[{"call":"knapsack::maximum_value(max_weight, items)","expected":"0"}]}},"64.02":{"id":"64.02","kind":64,"source":"aether","statement":["Write a function `exact::best_exact(int capacity, const std::vector<exact::Item>& items)` that returns the largest sum of values of items you can choose, each item at most once, whose weights add up to exactly `capacity`, or -1 when no choice does.","Write also the struct `exact::Item`, with two `int` members, `weight` then `value`.","Choosing no item makes weight 0.","Limits: 0 ≤ items ≤ 20; 0 ≤ capacity ≤ 1000; 1 ≤ each weight ≤ 1000; 1 ≤ each value ≤ 1000."],"examples":[{"input":"three items","output":""}],"tests":[{"input":"no items and no capacity","output":""},{"input":"no items","output":""},{"input":"no capacity","output":""},{"input":"item too heavy","output":""},{"input":"one item fills it","output":""},{"input":"many small beat one large","output":""},{"input":"the best part does not fill it","output":""},{"input":"cannot be made","output":""},{"input":"each item once","output":""},{"input":"largest","output":""},{"input":"largest that cannot be made","output":""}],"solution":{"lines":["#pragma once","","#include <algorithm>","#include <vector>","","namespace exact {","","struct Item {","    int weight {0};","    int value {0};","};","","int best_exact(int capacity,","               const std::vector<Item>& items)","{","    std::vector<int> best(capacity + 1, -1);","    best[0] = 0;","    for (const Item& item : items) {","        for (int w {capacity}; w >= item.weight; --w) {","            const int rest {best[w - item.weight]};","            if (rest >= 0) {","                best[w] = std::max(best[w], rest + item.value);","            }","        }","    }","    return best.back();","}","","}  // namespace exact"],"frame":[0,2,3,5,10,28],"labels":[{"at":7,"level":1,"text":"Write a struct that holds several values together."},{"at":12,"level":1,"text":"Write a function that keeps the best value for each weight, one item at a time."},{"at":15,"level":2,"text":"Start the best value for weight 0 at 0, and for each other weight at -1, the mark for none."},{"at":17,"level":2,"text":"For each item, keep the larger of the best value without it and with it, heaviest weight first, when the weight without it can be made."},{"at":25,"level":2,"text":"Give back the best value for the most weight."}],"blanks":[{"line":8,"from":16,"to":17},{"line":13,"from":15,"to":45},{"line":15,"from":40,"to":42},{"line":20,"from":16,"to":25},{"line":25,"from":11,"to":22}]},"fn":{"slug":"exact","commit":"","header":"exact.h","name":"exact_test.cpp","test":"#include \"exact.h\"\n#include \"test/catch.hpp\"\n\nTEST_CASE(\"three items\") { REQUIRE(exact::best_exact(5, {{2, 3}, {3, 4}, {4, 6}}) == 7); }\n#if defined(EXERCISM_RUN_ALL_TESTS)\nTEST_CASE(\"no items and no capacity\") { REQUIRE(exact::best_exact(0, {}) == 0); }\nTEST_CASE(\"no items\") { REQUIRE(exact::best_exact(3, {}) == -1); }\nTEST_CASE(\"no capacity\") { REQUIRE(exact::best_exact(0, {{1, 5}}) == 0); }\nTEST_CASE(\"item too heavy\") { REQUIRE(exact::best_exact(1, {{2, 5}}) == -1); }\nTEST_CASE(\"one item fills it\") { REQUIRE(exact::best_exact(4, {{4, 6}}) == 6); }\nTEST_CASE(\"many small beat one large\") { REQUIRE(exact::best_exact(6, {{1, 1}, {2, 2}, {3, 3}, {6, 5}}) == 6); }\nTEST_CASE(\"the best part does not fill it\") { REQUIRE(exact::best_exact(10, {{5, 10}, {5, 10}, {4, 100}}) == 20); }\nTEST_CASE(\"cannot be made\") { REQUIRE(exact::best_exact(7, {{2, 1}, {4, 1}, {6, 1}}) == -1); }\nTEST_CASE(\"each item once\") { REQUIRE(exact::best_exact(4, {{2, 9}}) == -1); }\nTEST_CASE(\"largest\") {\n    const std::vector<exact::Item> items(20, exact::Item {50, 1000});\n    REQUIRE(exact::best_exact(1000, items) == 20000);\n}\nTEST_CASE(\"largest that cannot be made\") {\n    const std::vector<exact::Item> items(20, exact::Item {2, 7});\n    REQUIRE(exact::best_exact(999, items) == -1);\n}\n#endif\n","setup":[],"calls":[{"call":"exact::best_exact(5, {{2, 3}, {3, 4}, {4, 6}})","expected":"7"}]}}}}
